import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Custom CUDA kernel for optimized cumulative sum
scan_kernel_source = """
#include <torch/extension.h>
#include <cub/block/block_scan.cuh>

template<int BLOCK_THREADS>
__global__ void scan_kernel(const float* input, float* output, int num_rows, int row_size) {
    const int row = blockIdx.x;
    const int tid = threadIdx.x;
    const int stride = BLOCK_THREADS;

    extern __shared__ float smem[];
    float* row_smem = smem + tid * row_size;

    // Load row into shared memory
    const float* row_ptr = input + row * row_size;
    for(int i = tid; i < row_size; i += stride) {
        row_smem[i] = row_ptr[i];
    }
    __syncthreads();

    // Sequential scan within shared memory
    float sum = 0;
    for(int i = 0; i < row_size; ++i) {
        sum += row_smem[i];
        row_smem[i] = sum;
    }
    __syncthreads();

    // Store results
    float* out_row = output + row * row_size;
    for(int i = tid; i < row_size; i += stride) {
        out_row[i] = row_smem[i];
    }
}

torch::Tensor scan_cuda(torch::Tensor input, int dim) {
    auto sizes = input.sizes().vec();
    const int ndim = sizes.size();

    // Permute dimensions to make scan dim last
    std::vector<int> perm(ndim);
    std::iota(perm.begin(), perm.end(), 0);
    std::swap(perm[dim], perm.back());
    auto input_perm = input.permute(perm).contiguous();

    // Reshape to 2D tensor
    const int num_rows = input_perm.numel() / sizes[dim];
    const int row_size = sizes[dim];
    input_perm = input_perm.view({num_rows, row_size});
    auto output = torch::zeros_like(input_perm);

    // Kernel configuration
    const int BLOCK_THREADS = 256;
    const int shared_mem = BLOCK_THREADS * row_size * sizeof(float);

    scan_kernel<BLOCK_THREADS><<<num_rows, BLOCK_THREADS, shared_mem>>>(
        input_perm.data_ptr<float>(),
        output.data_ptr<float>(),
        num_rows,
        row_size
    );

    // Restore original shape and permutation
    output = output.view(sizes);
    return output.permute(perm);
}
"""

scan_cpp_source = "torch::Tensor scan_cuda(torch::Tensor input, int dim);"

# Compile the CUDA extension
scan_module = load_inline(
    name='scan_module',
    cpp_sources=scan_cpp_source,
    cuda_sources=scan_kernel_source,
    functions=['scan_cuda'],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[]
)

class ModelNew(nn.Module):
    def __init__(self, dim):
        super(ModelNew, self).__init__()
        self.dim = dim

    def forward(self, x):
        return scan_module.scan_cuda(x, self.dim)
